import numpy as np
def equation(t, P, params):
    e5=np.exp(-0.5*t); e8=np.exp(-0.8*t); e1=np.exp(-0.1*t)
    B=[np.ones_like(t), t, e5, t*e5, e8, t*e8, e1]
    out=0.0
    for i in range(4):
        for j in range(len(B)):
            out=out+params[i*len(B)+j]*P**i*B[j]
    return out
